name: terraform_apply

on:
  workflow_call:
    inputs:
      ssh_image_tag:
        required: true
        type: string
      web_image_tag:
        required: true
        type: string
      nethack_image_tag:
        required: true
        type: string
      environment:
        required: false
        type: string
      source_ref:
        required: false
        type: string
        default: ""

jobs:
  terraform:
    name: terraform_apply
    runs-on: ubuntu-latest
    timeout-minutes: 15
    environment: ${{ inputs.environment }}
    env:
      TF_VAR_LOG_LEVEL: ${{ vars.LOG_LEVEL }}
      TF_VAR_DOMAIN: ${{ vars.DOMAIN }}
      TF_VAR_GRAFANA_URL: ${{ vars.GRAFANA_URL }}
      TF_VAR_SSH_IMAGE_TAG: ${{ inputs.ssh_image_tag }}
      TF_VAR_WEB_IMAGE_TAG: ${{ inputs.web_image_tag }}
      TF_VAR_NETHACK_IMAGE_TAG: ${{ inputs.nethack_image_tag }}
      TF_VAR_DOCKER_CONFIG_JSON: ${{ secrets.DOCKER_CONFIG_JSON }}
      TF_VAR_SSH_HOST_KEY: ${{ secrets.SSH_HOST_KEY }}
      TF_VAR_SSH_OPEN: ${{ vars.SSH_OPEN }}
      TF_VAR_MAX_CONNS_GLOBAL: ${{ vars.MAX_CONNS_GLOBAL }}
      TF_VAR_MAX_CONNS_PER_IP: ${{ vars.MAX_CONNS_PER_IP }}
      TF_VAR_SSH_IDLE_TIMEOUT: ${{ vars.SSH_IDLE_TIMEOUT }}
      TF_VAR_FRAME_DROP_LOG_EVERY: ${{ vars.FRAME_DROP_LOG_EVERY }}
      TF_VAR_SSH_MAX_ATTEMPTS_PER_IP: ${{ vars.SSH_MAX_ATTEMPTS_PER_IP }}
      TF_VAR_SSH_RATE_LIMIT_WINDOW_SECS: ${{ vars.SSH_RATE_LIMIT_WINDOW_SECS }}
      TF_VAR_WS_PAIR_MAX_ATTEMPTS_PER_IP: ${{ vars.WS_PAIR_MAX_ATTEMPTS_PER_IP }}
      TF_VAR_WS_PAIR_RATE_LIMIT_WINDOW_SECS: ${{ vars.WS_PAIR_RATE_LIMIT_WINDOW_SECS }}
      TF_VAR_DB_POOL_SIZE: ${{ vars.DB_POOL_SIZE }}
      TF_VAR_AI_ENABLED: ${{ vars.AI_ENABLED }}
      TF_VAR_AI_MODEL: ${{ vars.AI_MODEL }}
      TF_VAR_AI_API_KEY: ${{ secrets.AI_API_KEY }}
      TF_VAR_YOUTUBE_API_KEY: ${{ secrets.YOUTUBE_API_KEY }}
      TF_VAR_REBELS_ENABLED: ${{ vars.REBELS_ENABLED }}
      TF_VAR_REBELS_HOST: ${{ vars.REBELS_HOST }}
      TF_VAR_REBELS_PORT: ${{ vars.REBELS_PORT }}
      TF_VAR_NETHACK_ENABLED: ${{ vars.NETHACK_ENABLED }}
      TF_VAR_VOICE_ENABLED: ${{ vars.VOICE_ENABLED }}
      TF_VAR_VOICE_ROOM: ${{ vars.VOICE_ROOM }}
      TF_VAR_LIVEKIT_SUBDOMAIN: ${{ vars.LIVEKIT_SUBDOMAIN }}
      TF_VAR_LIVEKIT_IMAGE: ${{ vars.LIVEKIT_IMAGE }}
      TF_VAR_LIVEKIT_LOG_LEVEL: ${{ vars.LIVEKIT_LOG_LEVEL }}
      TF_VAR_LIVEKIT_API_KEY: ${{ vars.LIVEKIT_API_KEY }}
      TF_VAR_LIVEKIT_RTC_TCP_PORT: ${{ vars.LIVEKIT_RTC_TCP_PORT }}
      TF_VAR_LIVEKIT_RTC_UDP_PORT: ${{ vars.LIVEKIT_RTC_UDP_PORT }}
      TF_VAR_LIVEKIT_RTC_USE_EXTERNAL_IP: ${{ vars.LIVEKIT_RTC_USE_EXTERNAL_IP }}
      TF_VAR_LIVEKIT_TURN_ENABLED: ${{ vars.LIVEKIT_TURN_ENABLED }}
      TF_VAR_LIVEKIT_TURN_UDP_PORT: ${{ vars.LIVEKIT_TURN_UDP_PORT }}
      TF_VAR_LIVEKIT_TURN_TLS_PORT: ${{ vars.LIVEKIT_TURN_TLS_PORT }}
      TF_VAR_IRC_ENABLED: ${{ vars.IRC_ENABLED }}
      TF_VAR_IRC_HOST: ${{ vars.IRC_HOST }}
      TF_VAR_IRC_PORT: ${{ vars.IRC_PORT }}
      TF_VAR_IRC_MAX_CONNS_GLOBAL: ${{ vars.IRC_MAX_CONNS_GLOBAL }}
      TF_VAR_IRC_MAX_CONNS_PER_USER: ${{ vars.IRC_MAX_CONNS_PER_USER }}
      TF_VAR_IRC_MAX_AUTH_FAILURES_PER_IP: ${{ vars.IRC_MAX_AUTH_FAILURES_PER_IP }}
      TF_VAR_IRC_AUTH_FAILURE_WINDOW_SECS: ${{ vars.IRC_AUTH_FAILURE_WINDOW_SECS }}
      TF_VAR_VOTE_SWITCH_INTERVAL_SECS: ${{ vars.VOTE_SWITCH_INTERVAL_SECS }}
      TF_VAR_S3_ACCESS_KEY_ID: ${{ secrets.S3_ACCESS_KEY_ID }}
      TF_VAR_S3_SECRET_ACCESS_KEY: ${{ secrets.S3_SECRET_ACCESS_KEY }}
      TF_VAR_S3_ENDPOINT: ${{ vars.S3_ENDPOINT }}
      TF_VAR_DB_BACKUPS_BUCKET: ${{ vars.DB_BACKUPS_BUCKET }}
      TF_VAR_FILES_BUCKET: ${{ vars.FILES_BUCKET }}
      TF_VAR_FILES_PUBLIC_BASE_URL: ${{ vars.FILES_PUBLIC_BASE_URL }}
      AWS_ACCESS_KEY_ID: ${{ secrets.S3_ACCESS_KEY_ID }}
      AWS_SECRET_ACCESS_KEY: ${{ secrets.S3_SECRET_ACCESS_KEY }}
    steps:
      - name: checkout
        uses: actions/checkout@v5
        with:
          ref: ${{ inputs.source_ref || github.ref }}

      - name: setup_kubectl
        uses: azure/setup-kubectl@v5

      - name: set_kubernetes_context
        uses: azure/k8s-set-context@v5
        with:
          kubeconfig: ${{ secrets.KUBE_CONFIG }}

      - name: set_kubeconfig_path_for_terraform
        run: echo "TF_VAR_KUBE_CONFIG_PATH=$KUBECONFIG" >> "$GITHUB_ENV"

      - name: setup_terraform
        uses: hashicorp/setup-terraform@v4

      - name: terraform_init
        working-directory: ./infra
        run: terraform init

      - name: terraform_validate
        working-directory: ./infra
        run: terraform validate

      # CRD-installing operators must be applied first because kubernetes_manifest
      # resources validate against the API schema at plan time.
      - name: terraform_apply_operators
        working-directory: ./infra
        run: |
          terraform apply -auto-approve -compact-warnings \
            -target=helm_release.cert_manager \
            -target=helm_release.cloudnativepg \
            -target=helm_release.barman_cloud_plugin \
            -target=helm_release.local_path_provisioner

      - name: terraform_apply
        working-directory: ./infra
        run: terraform apply -auto-approve

